import json, pathlib, re

def load(fp):
    texts=[]
    for line in pathlib.Path(fp).open():
        try:
            o=json.loads(line)
        except Exception:
            continue
        role=o.get("role") or ""
        msg=o.get("message") if isinstance(o.get("message"), dict) else {}
        c=msg.get("content")
        text=""
        if isinstance(c, str):
            text=c
        elif isinstance(c, list):
            for part in c:
                if isinstance(part, dict) and part.get("type")=="text":
                    text+=part.get("text") or ""
        if text.strip():
            texts.append((role, text))
    return texts

def users_on_16(texts):
    out=[]
    for role,text in texts:
        if role!="user" or "user_query" not in text:
            continue
        m=re.search(r"<timestamp>(.*?)</timestamp>", text, re.S)
        ts=m.group(1).strip() if m else "?"
        if "Oct 16" not in ts and "Friday, Oct 16" not in ts:
            continue
        m2=re.search(r"<user_query>\s*(.*)", text, re.S)
        q=re.sub(r"\s+"," ", (m2.group(1) if m2 else text))[:420]
        out.append((ts, q))
    return out

